<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cola de soporte | Helpdesk Carrousel</title><link rel="stylesheet" href="<?= htmlspecialchars(APP_PUBLIC_PATH) ?>/assets/css/app.css"><link rel="stylesheet" href="<?= htmlspecialchars(APP_PUBLIC_PATH) ?>/assets/css/layout-fixes.css"></head><body><div class="brand-strip"></div><main class="content" style="max-width:1200px;margin:auto"><div class="page-heading"><div><h1 class="page-title">Cola de soporte</h1><p class="page-subtitle">Casos disponibles para tomar.</p></div><a class="btn btn-outline-secondary" href="<?= APP_BASE_URL ?>/dashboard">Dashboard</a></div><?php if(!empty($flash)): ?><div class="alert"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?><section class="card"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Ticket</th><th>Fecha</th><th>Prioridad</th><th>Parque</th><th>Categoría</th><th>Asunto</th><th></th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td><strong><?= htmlspecialchars($t['ticket_number']) ?></strong></td><td><?= htmlspecialchars($t['created_at']) ?></td><td><?= htmlspecialchars($t['priority']) ?></td><td><?= htmlspecialchars($t['park_name']??'—') ?></td><td><?= htmlspecialchars($t['category_name']??'—') ?></td><td><?= htmlspecialchars($t['subject']) ?></td><td><form method="post" action="<?= APP_BASE_URL ?>/tickets/claim"><input type="hidden" name="_csrf" value="<?= Csrf::token() ?>"><input type="hidden" name="ticket_id" value="<?= (int)$t['id'] ?>"><button class="btn btn-primary btn-sm">Tomar caso</button></form></td></tr><?php endforeach; ?><?php if(!$tickets): ?><tr><td colspan="7">No hay casos disponibles.</td></tr><?php endif; ?></tbody></table></div></div></section></main></body></html>